"""A recoverable, idempotent, JSON-file backed inbox.

The public contract lives in README.md:

* ``Inbox(path)`` loads (or treats as empty) a single JSON document shaped
  ``{'version': 1, 'records': [...]}``; records keep submission order and have
  exactly the fields ``id``, ``payload`` and ``status`` with status one of
  ``pending``, ``running``, ``completed`` or ``interrupted``.
* Every mutation is persisted durably *before* it is acknowledged: a temporary
  file in the destination directory is written, its data is flushed and
  ``os.fsync``-ed, and the destination is then replaced atomically with
  ``os.replace``.  A failing save raises the original ``OSError`` and leaves the
  in-memory snapshot exactly as it was before the operation.
* Loading a document turns every ``running`` record into ``interrupted`` and
  persists that recovery before returning.  ``pending`` records never auto-run.

Only the Python standard library is used.
"""

from __future__ import annotations

import copy
import json
import math
import os
import tempfile

__all__ = ["Inbox"]

VERSION = 1
MAX_ID_LENGTH = 64

PENDING = "pending"
RUNNING = "running"
COMPLETED = "completed"
INTERRUPTED = "interrupted"
STATUSES = frozenset({PENDING, RUNNING, COMPLETED, INTERRUPTED})

RECORD_FIELDS = frozenset({"id", "payload", "status"})
DOCUMENT_FIELDS = frozenset({"version", "records"})

_CANONICAL_ARGS = {
    "sort_keys": True,
    "ensure_ascii": False,
    "separators": (",", ":"),
    "allow_nan": False,
}

# Module level aliases for the two durability primitives.  A test may patch
# either these names or their ``os`` counterparts, so both are honoured at call
# time instead of the function object being captured once at import time.
_ORIGINAL_FSYNC = os.fsync
_ORIGINAL_REPLACE = os.replace
fsync = _ORIGINAL_FSYNC
replace = _ORIGINAL_REPLACE


def _fsync(descriptor):
    function = globals().get("fsync") or _ORIGINAL_FSYNC
    if function is _ORIGINAL_FSYNC:
        function = getattr(os, "fsync", _ORIGINAL_FSYNC)
    return function(descriptor)


def _replace(source, destination):
    function = globals().get("replace") or _ORIGINAL_REPLACE
    if function is _ORIGINAL_REPLACE:
        function = getattr(os, "replace", _ORIGINAL_REPLACE)
    return function(source, destination)


# --------------------------------------------------------------------------- #
# validation helpers
# --------------------------------------------------------------------------- #
def _validate_identifier(identifier):
    """Return a valid record id or raise ValueError."""
    if not isinstance(identifier, str):
        raise ValueError("record id must be a string")
    if not identifier:
        raise ValueError("record id must not be empty")
    if len(identifier) > MAX_ID_LENGTH:
        raise ValueError("record id must be at most %d characters" % MAX_ID_LENGTH)
    return identifier


def _check_value(value, active):
    """Recursively require a JSON value; raise ValueError otherwise."""

    if value is None:
        return
    if isinstance(value, bool):  # before int: bool is an int subclass
        return
    if isinstance(value, int):
        return
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError("payload numbers must be finite")
        return
    if isinstance(value, str):
        return

    if isinstance(value, list):
        marker = id(value)
        if marker in active:
            raise ValueError("payload must not contain circular references")
        active.add(marker)
        try:
            for item in value:
                _check_value(item, active)
        finally:
            active.discard(marker)
        return

    if isinstance(value, dict):
        marker = id(value)
        if marker in active:
            raise ValueError("payload must not contain circular references")
        active.add(marker)
        try:
            for name, item in value.items():
                if not isinstance(name, str):
                    raise ValueError("payload objects must use string keys")
                _check_value(item, active)
        finally:
            active.discard(marker)
        return

    raise ValueError(
        "payload contains a value that is not JSON serialisable: %s" % (type(value).__name__,)
    )


def _validate_payload(payload):
    """Return ``payload`` itself when it is a valid JSON value."""
    _check_value(payload, set())
    return payload


def _canonical(payload):
    """Canonical JSON text used for payload identity comparisons."""
    return json.dumps(payload, **_CANONICAL_ARGS)


def _detached_record(record):
    """A deep, fully independent copy of a stored record."""
    return {
        "id": record["id"],
        "payload": copy.deepcopy(record["payload"]),
        "status": record["status"],
    }


def _validate_record(raw, seen_ids, origin):
    if not isinstance(raw, dict):
        raise ValueError("%s: every record must be a JSON object" % origin)
    if set(raw) != RECORD_FIELDS:
        raise ValueError("%s: records must have exactly the fields id, payload, status" % origin)

    identifier = _validate_identifier(raw["id"])
    if identifier in seen_ids:
        raise ValueError("%s: duplicate stored record id %r" % (origin, identifier))
    seen_ids.add(identifier)

    status = raw["status"]
    if not isinstance(status, str) or status not in STATUSES:
        raise ValueError("%s: record %r has an invalid status" % (origin, identifier))

    payload = raw["payload"]
    _validate_payload(payload)

    return {"id": identifier, "payload": payload, "status": status}


def _validate_document(document, origin):
    if not isinstance(document, dict):
        raise ValueError("%s: the document must be a JSON object" % origin)
    if set(document) != DOCUMENT_FIELDS:
        raise ValueError("%s: the document must contain exactly version and records" % origin)

    version = document["version"]
    if isinstance(version, bool) or not isinstance(version, int) or version != VERSION:
        raise ValueError("%s: unsupported document version %r" % (origin, version))

    records = document["records"]
    if not isinstance(records, list):
        raise ValueError("%s: 'records' must be a list" % origin)

    seen_ids = set()
    return [_validate_record(raw, seen_ids, origin) for raw in records]


# --------------------------------------------------------------------------- #
# public API
# --------------------------------------------------------------------------- #
class Inbox:
    """A single-process, single-writer, recoverable idempotent inbox."""

    def __init__(self, path):
        self.path = path
        self._target = os.fspath(path)
        self._records = []

        records = self._load()
        recovered = False
        for record in records:
            if record["status"] == RUNNING:
                record["status"] = INTERRUPTED
                recovered = True
        if recovered:
            # Persist the recovery before the instance becomes usable.
            self._save(records)
        self._records = records

    # -- read side ---------------------------------------------------------- #
    def snapshot(self):
        """A detached deep copy of the records in submission order."""
        return [_detached_record(record) for record in self._records]

    # -- write side --------------------------------------------------------- #
    def submit(self, identifier, payload):
        """Add a new pending record, or return the record of an identical repeat."""
        _validate_identifier(identifier)
        _validate_payload(payload)
        canonical = _canonical(payload)

        existing = self._find(identifier)
        if existing is not None:
            if _canonical(existing["payload"]) != canonical:
                raise ValueError("conflicting payload for existing id %r" % (identifier,))
            return _detached_record(existing)

        record = {"id": identifier, "payload": copy.deepcopy(payload), "status": PENDING}
        records = self._records + [record]
        self._save(records)  # raise before acknowledging the new state
        self._records = records
        return _detached_record(record)

    def start_next(self):
        """Move the first pending record to running and return a detached copy."""
        if any(record["status"] == RUNNING for record in self._records):
            raise RuntimeError("a record is already running")

        index = self._first_index(PENDING)
        if index is None:
            return None

        records = list(self._records)
        record = dict(records[index])
        record["status"] = RUNNING
        records[index] = record
        self._save(records)
        self._records = records
        return _detached_record(record)

    def finish(self, identifier):
        """Complete a running record; completing a completed record is a no-op."""
        index = self._index_of(identifier)
        if index is None:
            raise KeyError(identifier)

        record = self._records[index]
        status = record["status"]
        if status == COMPLETED:
            return _detached_record(record)
        if status != RUNNING:
            raise ValueError("cannot finish a %s record" % status)

        records = list(self._records)
        records[index] = {"id": record["id"], "payload": record["payload"], "status": COMPLETED}
        self._save(records)
        self._records = records
        return _detached_record(records[index])

    # -- lookups ------------------------------------------------------------ #
    def _index_of(self, identifier):
        for index, record in enumerate(self._records):
            if record["id"] == identifier:
                return index
        return None

    def _first_index(self, status):
        for index, record in enumerate(self._records):
            if record["status"] == status:
                return index
        return None

    def _find(self, identifier):
        index = self._index_of(identifier)
        return None if index is None else self._records[index]

    # -- persistence -------------------------------------------------------- #
    def _load(self):
        try:
            with open(
                self._target, "r", encoding="utf-8", errors="surrogatepass", newline=""
            ) as handle:
                text = handle.read()
        except FileNotFoundError:
            return []

        try:
            document = json.loads(text)
        except ValueError as error:
            raise ValueError("%s: malformed JSON: %s" % (self._target, error)) from error
        return _validate_document(document, self._target)

    def _save(self, records):
        document = {
            "version": VERSION,
            "records": [
                {"id": record["id"], "payload": record["payload"], "status": record["status"]}
                for record in records
            ],
        }

        target = self._target
        directory = os.path.dirname(os.path.abspath(target))
        os.makedirs(directory, exist_ok=True)

        descriptor, temporary = tempfile.mkstemp(
            prefix=os.path.basename(target) + ".", suffix=".tmp", dir=directory
        )
        try:
            with os.fdopen(
                descriptor, "w", encoding="utf-8", errors="surrogatepass", newline="\n"
            ) as handle:
                json.dump(document, handle, **_CANONICAL_ARGS)
                handle.flush()
                _fsync(handle.fileno())
            _replace(temporary, target)
        except BaseException:
            try:
                os.unlink(temporary)
            except OSError:
                pass
            raise

    def __repr__(self):  # pragma: no cover - debugging convenience
        return "<Inbox %r records=%d>" % (self._target, len(self._records))

