class Decoder:
    _LENGTH = 0
    _PAYLOAD = 1
    _COMMA = 2

    def __init__(self, max_size=1024):
        if isinstance(max_size, bool) or not isinstance(max_size, int):
            raise ValueError("max_size must be a nonnegative int")
        if max_size < 0:
            raise ValueError("max_size must be a nonnegative int")
        self._max_size = max_size
        self._state = self._LENGTH
        self._digits = 0
        self._value = 0
        self._leading_zero = False
        self._expected = 0
        self._payload = None
        self._failed = False
        self._done = False

    def _reset_frame(self):
        self._state = self._LENGTH
        self._digits = 0
        self._value = 0
        self._leading_zero = False
        self._expected = 0
        self._payload = None

    def feed(self, data):
        if self._failed or self._done:
            raise ValueError("decoder is closed")
        if not isinstance(data, (bytes, bytearray)):
            raise TypeError("data must be bytes or bytearray")
        if isinstance(data, bytearray):
            data = bytes(data)

        results = []
        i = 0
        n = len(data)
        try:
            while i < n:
                state = self._state
                if state == self._LENGTH:
                    b = data[i]
                    if 48 <= b <= 57:
                        digit = b - 48
                        if self._leading_zero:
                            raise ValueError("leading zero in length")
                        if self._digits == 0 and digit == 0:
                            self._leading_zero = True
                            self._digits = 1
                            self._value = 0
                            i += 1
                            continue
                        self._value = self._value * 10 + digit
                        if self._value > self._max_size:
                            raise ValueError("length exceeds max_size")
                        self._digits += 1
                        i += 1
                    elif b == 58:
                        if self._digits == 0:
                            raise ValueError("empty length")
                        self._expected = self._value
                        if self._expected == 0:
                            self._payload = None
                            self._state = self._COMMA
                        else:
                            self._payload = bytearray()
                            self._state = self._PAYLOAD
                        i += 1
                    else:
                        raise ValueError("invalid length byte")
                elif state == self._PAYLOAD:
                    need = self._expected - len(self._payload)
                    take = n - i
                    if take > need:
                        take = need
                    if take:
                        self._payload += data[i:i + take]
                        i += take
                    if len(self._payload) >= self._expected:
                        self._state = self._COMMA
                else:
                    if data[i] != 44:
                        raise ValueError("missing frame terminator")
                    payload = bytes(self._payload) if self._payload else b""
                    try:
                        results.append(payload.decode("utf-8"))
                    except UnicodeDecodeError:
                        raise ValueError("invalid utf-8 payload")
                    self._reset_frame()
                    i += 1
        except ValueError:
            self._failed = True
            self._payload = None
            raise
        return results

    def finish(self):
        if self._failed or self._done:
            raise ValueError("decoder is closed")
        if self._state == self._LENGTH and self._digits == 0:
            self._done = True
            return None
        self._failed = True
        self._payload = None
        raise ValueError("incomplete frame at end of input")

