"""Recoverable idempotent JSON-file inbox (single process, single writer)."""

import copy
import json
import math
import os
import tempfile

STATES = ("pending", "running", "completed", "interrupted")

_CANON_KWARGS = dict(
    sort_keys=True,
    ensure_ascii=False,
    separators=(",", ":"),
    allow_nan=False,
)


def _validate_id(identifier):
    if not isinstance(identifier, str) or isinstance(identifier, bool):
        raise ValueError("id must be a string")
    if not identifier:
        raise ValueError("id must be nonempty")
    if len(identifier) > 64:
        raise ValueError("id must be at most 64 characters")


def _validate_payload(value):
    if value is None:
        return
    if isinstance(value, bool):
        return
    if isinstance(value, str):
        return
    if isinstance(value, int):
        return
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError("payload numbers must be finite")
        return
    if isinstance(value, list):
        for item in value:
            _validate_payload(item)
        return
    if isinstance(value, dict):
        for key, item in value.items():
            if not isinstance(key, str):
                raise ValueError("payload object keys must be strings")
            _validate_payload(item)
        return
    raise ValueError("payload is not a valid JSON value")


def _canonical(value):
    return json.dumps(value, **_CANON_KWARGS)


class Inbox:
    def __init__(self, path):
        self.path = path
        self._records = self._load()
        if any(record["status"] == "running" for record in self._records):
            recovered = [
                dict(record, status="interrupted")
                if record["status"] == "running"
                else record
                for record in self._records
            ]
            self._commit(recovered)

    # -- persistence ---------------------------------------------------
    def _document(self, records):
        return {"version": 1, "records": records}

    def _save(self, records):
        document = self._document(records)
        target = os.fspath(self.path)
        directory = os.path.dirname(os.path.abspath(target))
        os.makedirs(directory, exist_ok=True)
        fd, tmp = tempfile.mkstemp(dir=directory, prefix=".inbox-", suffix=".tmp")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as handle:
                json.dump(document, handle, ensure_ascii=False, allow_nan=False)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(tmp, target)
        except BaseException:
            try:
                if os.path.exists(tmp):
                    os.remove(tmp)
            except OSError:
                pass
            raise

    def _commit(self, records):
        self._save(records)
        self._records = records

    def _load(self):
        target = os.fspath(self.path)
        try:
            with open(target, "r", encoding="utf-8") as handle:
                text = handle.read()
        except FileNotFoundError:
            return []
        except UnicodeDecodeError as exc:
            raise ValueError("inbox file is not valid UTF-8 JSON") from exc
        try:
            document = json.loads(text)
        except ValueError as exc:
            raise ValueError("inbox file is malformed JSON") from exc
        return self._validate_document(document)

    def _validate_document(self, document):
        if not isinstance(document, dict):
            raise ValueError("inbox document must be an object")
        version = document.get("version")
        if isinstance(version, bool) or not isinstance(version, int) or version != 1:
            raise ValueError("inbox document version must be 1")
        records = document.get("records")
        if not isinstance(records, list):
            raise ValueError("inbox document records must be a list")
        seen = set()
        validated = []
        for record in records:
            if not isinstance(record, dict):
                raise ValueError("record must be an object")
            if set(record.keys()) != {"id", "payload", "status"}:
                raise ValueError("record must have exactly id, payload, status")
            identifier = record["id"]
            _validate_id(identifier)
            status = record["status"]
            if not isinstance(status, str) or status not in STATES:
                raise ValueError("record has an invalid status")
            _validate_payload(record["payload"])
            if identifier in seen:
                raise ValueError("duplicate record id")
            seen.add(identifier)
            validated.append(copy.deepcopy(record))
        return validated

    # -- public API ----------------------------------------------------
    def submit(self, identifier, payload):
        _validate_id(identifier)
        _validate_payload(payload)
        canonical = _canonical(payload)
        for record in self._records:
            if record["id"] == identifier:
                if _canonical(record["payload"]) == canonical:
                    return copy.deepcopy(record)
                raise ValueError("conflicting payload for existing id")
        new_record = {
            "id": identifier,
            "payload": copy.deepcopy(payload),
            "status": "pending",
        }
        self._commit(self._records + [new_record])
        return copy.deepcopy(new_record)

    def start_next(self):
        if any(record["status"] == "running" for record in self._records):
            raise RuntimeError("a record is already running")
        for index, record in enumerate(self._records):
            if record["status"] == "pending":
                updated = dict(record, status="running")
                records = list(self._records)
                records[index] = updated
                self._commit(records)
                return copy.deepcopy(updated)
        return None

    def finish(self, identifier):
        for index, record in enumerate(self._records):
            if record["id"] == identifier:
                if record["status"] == "completed":
                    return copy.deepcopy(record)
                if record["status"] != "running":
                    raise ValueError("only running records can be finished")
                updated = dict(record, status="completed")
                records = list(self._records)
                records[index] = updated
                self._commit(records)
                return copy.deepcopy(updated)
        raise KeyError(identifier)

    def snapshot(self):
        return copy.deepcopy(self._records)

"""A recoverable, idempotent, single-writer JSON-file inbox.

The persistent document has the shape::

    {"version": 1, "records": [ {id, payload, status}, ... ]}

Records are kept in original submission order.  Every mutating operation is
saved durably (same-directory temp file + flush + fsync + os.replace) before
the new state is acknowledged.
"""

from __future__ import annotations

import copy
import json
import math
import os
import tempfile
from pathlib import Path

__all__ = ["Inbox"]

_VERSION = 1
_STATUSES = ("pending", "running", "completed", "interrupted")
_RECORD_KEYS = frozenset(("id", "payload", "status"))
_DOCUMENT_KEYS = frozenset(("version", "records"))
_MAX_ID_LENGTH = 64

_DUMPS_KWARGS = dict(
    sort_keys=True,
    ensure_ascii=False,
    separators=(",", ":"),
    allow_nan=False,
)


def _validate_payload(value):
    """Recursively validate that *value* is a JSON value, raising ValueError."""
    if value is None or isinstance(value, bool):
        return
    if isinstance(value, str):
        return
    if isinstance(value, int):
        return
    if isinstance(value, float):
        if math.isfinite(value):
            return
        raise ValueError("payload contains a non-finite number")
    if isinstance(value, list):
        for item in value:
            _validate_payload(item)
        return
    if isinstance(value, dict):
        for key, item in value.items():
            if not isinstance(key, str):
                raise ValueError("payload object keys must be strings")
            _validate_payload(item)
        return
    raise ValueError("payload contains a value that is not valid JSON")


def _validate_identifier(identifier):
    if not isinstance(identifier, str) or isinstance(identifier, bool):
        raise ValueError("id must be a nonempty string of at most 64 characters")
    if not identifier or len(identifier) > _MAX_ID_LENGTH:
        raise ValueError("id must be a nonempty string of at most 64 characters")


def _canonical(payload):
    """Canonical JSON representation used to compare payloads for equality."""
    return json.dumps(payload, **_DUMPS_KWARGS)


def _validate_record(record):
    if not isinstance(record, dict):
        raise ValueError("each record must be an object")
    if set(record.keys()) != _RECORD_KEYS:
        raise ValueError("each record must contain exactly id, payload, status")
    _validate_identifier(record["id"])
    if not isinstance(record["status"], str) or record["status"] not in _STATUSES:
        raise ValueError("record has an invalid status")
    _validate_payload(record["payload"])


class Inbox:
    """A durable JSON-file inbox."""

    def __init__(self, path):
        self.path = Path(path)
        self._records = self._load()

    # ------------------------------------------------------------------
    # persistence
    # ------------------------------------------------------------------
    def _load(self):
        path = self.path
        try:
            with open(path, "r", encoding="utf-8") as handle:
                raw = handle.read()
        except FileNotFoundError:
            return []

        # json.JSONDecodeError is a ValueError subclass.
        document = json.loads(raw)

        if not isinstance(document, dict):
            raise ValueError("document must be a JSON object")
        if set(document.keys()) != _DOCUMENT_KEYS:
            raise ValueError("document must contain exactly version and records")
        version = document["version"]
        if isinstance(version, bool) or not isinstance(version, int) or version != _VERSION:
            raise ValueError("unsupported document version")

        records = document["records"]
        if not isinstance(records, list):
            raise ValueError("records must be a list")

        seen = set()
        for record in records:
            _validate_record(record)
            if record["id"] in seen:
                raise ValueError("duplicate record id in document")
            seen.add(record["id"])

        # Recovery: any running record becomes interrupted and is persisted
        # before the constructor returns.
        if any(record["status"] == "running" for record in records):
            recovered = copy.deepcopy(records)
            for record in recovered:
                if record["status"] == "running":
                    record["status"] = "interrupted"
            self._save(recovered)
            return recovered

        return copy.deepcopy(records)

    def _save(self, records):
        """Durably write *records*; raise without touching self on failure."""
        document = {"version": _VERSION, "records": records}
        data = json.dumps(document, **_DUMPS_KWARGS)

        path = self.path
        parent = path.parent
        parent.mkdir(parents=True, exist_ok=True)

        fd, tmp_name = tempfile.mkstemp(
            prefix=path.name + ".", suffix=".tmp", dir=str(parent)
        )
        try:
            try:
                handle = os.fdopen(fd, "w", encoding="utf-8", newline="")
            except BaseException:
                try:
                    os.close(fd)
                except OSError:
                    pass
                raise
            with handle:
                handle.write(data)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(tmp_name, str(path))
        except BaseException:
            try:
                os.remove(tmp_name)
            except OSError:
                pass
            raise

    # ------------------------------------------------------------------
    # public API
    # ------------------------------------------------------------------
    def submit(self, identifier, payload):
        _validate_identifier(identifier)
        _validate_payload(payload)
        incoming = _canonical(payload)

        for record in self._records:
            if record["id"] == identifier:
                if _canonical(record["payload"]) == incoming:
                    return copy.deepcopy(record)
                raise ValueError("conflicting payload for existing id")

        new_record = {
            "id": identifier,
            "payload": copy.deepcopy(payload),
            "status": "pending",
        }
        new_records = copy.deepcopy(self._records)
        new_records.append(new_record)
        self._save(new_records)
        self._records = new_records
        return copy.deepcopy(new_record)

    def start_next(self):
        if any(record["status"] == "running" for record in self._records):
            raise RuntimeError("a record is already running")

        for index, record in enumerate(self._records):
            if record["status"] == "pending":
                new_records = copy.deepcopy(self._records)
                new_records[index]["status"] = "running"
                self._save(new_records)
                self._records = new_records
                return copy.deepcopy(new_records[index])
        return None

    def finish(self, identifier):
        for index, record in enumerate(self._records):
            if record["id"] != identifier:
                continue
            if record["status"] == "completed":
                return copy.deepcopy(record)
            if record["status"] != "running":
                raise ValueError(
                    "only a running record can be completed"
                )
            new_records = copy.deepcopy(self._records)
            new_records[index]["status"] = "completed"
            self._save(new_records)
            self._records = new_records
            return copy.deepcopy(new_records[index])
        raise KeyError(identifier)

    def snapshot(self):
        return copy.deepcopy(self._records)

"""A recoverable, idempotent, single-writer JSON-file inbox.

Public API (see README.md):

    Inbox(path)
    .submit(identifier, payload) -> detached record
    .start_next()                -> detached record | None
    .finish(identifier)          -> detached record
    .snapshot()                  -> detached list of records

The persistent document has the shape::

    {"version": 1, "records": [ {"id": ..., "payload": ..., "status": ...}, ... ]}

Only the Python standard library is used.
"""

from __future__ import annotations

import copy
import json
import math
import os
import tempfile
from pathlib import Path

__all__ = ["Inbox"]

_VALID_STATUSES = frozenset({"pending", "running", "completed", "interrupted"})


# ---------------------------------------------------------------------------
# Validation helpers
# ---------------------------------------------------------------------------
def _validate_identifier(identifier):
    """Validate an id: a nonempty string of at most 64 characters."""
    if not isinstance(identifier, str):
        raise ValueError("id must be a string")
    if len(identifier) == 0:
        raise ValueError("id must be a nonempty string")
    if len(identifier) > 64:
        raise ValueError("id must be at most 64 characters")
    return identifier


def _validate_payload(payload):
    """Validate that ``payload`` is a JSON value.

    Allowed: null, bool, finite int/float, str, list of JSON values and
    objects with string keys whose values are JSON values.  Anything else
    (tuples, sets, bytes, non-finite floats, non-string object keys, ...)
    raises ``ValueError``.
    """
    if payload is None:
        return
    if isinstance(payload, bool):
        return
    if isinstance(payload, str):
        return
    if isinstance(payload, int):
        return
    if isinstance(payload, float):
        if not math.isfinite(payload):
            raise ValueError("payload numbers must be finite")
        return
    if isinstance(payload, list):
        for item in payload:
            _validate_payload(item)
        return
    if isinstance(payload, dict):
        for key, value in payload.items():
            if not isinstance(key, str):
                raise ValueError("payload object keys must be strings")
            _validate_payload(value)
        return
    raise ValueError("payload is not a JSON value: %r" % (type(payload).__name__,))


def _canonical(payload):
    """Return the canonical string used to compare payloads for equality."""
    return json.dumps(
        payload,
        sort_keys=True,
        ensure_ascii=False,
        separators=(",", ":"),
        allow_nan=False,
    )


def _detached(value):
    """Return a deep copy so callers can never alias internal state."""
    return copy.deepcopy(value)


# ---------------------------------------------------------------------------
# Document (de)serialisation / schema validation
# ---------------------------------------------------------------------------
def _parse_record(record, seen_ids):
    if not isinstance(record, dict):
        raise ValueError("record must be a JSON object")
    if set(record.keys()) != {"id", "payload", "status"}:
        raise ValueError("record must have exactly id, payload and status")
    identifier = record["id"]
    _validate_identifier(identifier)
    if identifier in seen_ids:
        raise ValueError("duplicate record id: %r" % (identifier,))
    seen_ids.add(identifier)
    status = record["status"]
    if not isinstance(status, str) or status not in _VALID_STATUSES:
        raise ValueError("invalid record status: %r" % (status,))
    payload = record["payload"]
    _validate_payload(payload)
    return {"id": identifier, "payload": payload, "status": status}


def _parse_document(document):
    if not isinstance(document, dict):
        raise ValueError("document must be a JSON object")
    if set(document.keys()) != {"version", "records"}:
        raise ValueError("document must have exactly version and records")
    version = document["version"]
    if isinstance(version, bool) or not isinstance(version, int) or version != 1:
        raise ValueError("unsupported document version: %r" % (version,))
    raw_records = document["records"]
    if not isinstance(raw_records, list):
        raise ValueError("records must be a JSON array")
    seen_ids = set()
    return [_parse_record(record, seen_ids) for record in raw_records]


# ---------------------------------------------------------------------------
# The inbox
# ---------------------------------------------------------------------------
class Inbox:
    """A durable, idempotent, JSON-file-backed inbox."""

    def __init__(self, path):
        self.path = path
        self._path = Path(path)
        self._records = []
        self._load()

    # -- persistence -------------------------------------------------------
    def _write(self, records):
        """Durably and atomically persist ``records``.

        Writes to a temporary file in the destination directory, flushes and
        ``os.fsync``-es it, then atomically replaces the destination with
        ``os.replace``.  Any ``OSError`` propagates unchanged.
        """
        document = {"version": 1, "records": records}
        data = json.dumps(document, ensure_ascii=False, allow_nan=False)

        directory = self._path.parent
        directory.mkdir(parents=True, exist_ok=True)

        fd, tmp_name = tempfile.mkstemp(
            dir=str(directory), prefix=".inbox-", suffix=".tmp"
        )
        try:
            with os.fdopen(fd, "w", encoding="utf-8", newline="") as handle:
                handle.write(data)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(tmp_name, self._path)
        except BaseException:
            try:
                os.unlink(tmp_name)
            except OSError:
                pass
            raise

    # -- loading -----------------------------------------------------------
    def _load(self):
        try:
            text = self._path.read_text(encoding="utf-8")
        except FileNotFoundError:
            self._records = []
            return
        try:
            document = json.loads(text)
        except ValueError as exc:
            raise ValueError("malformed inbox JSON: %s" % (exc,)) from exc

        records = _parse_document(document)

        # Recovery: any running record is converted to interrupted and this
        # recovery is persisted before the instance is usable.
        if any(record["status"] == "running" for record in records):
            for record in records:
                if record["status"] == "running":
                    record["status"] = "interrupted"
            self._write(records)

        self._records = records

    # -- public API --------------------------------------------------------
    def submit(self, identifier, payload):
        _validate_identifier(identifier)
        _validate_payload(payload)
        key = _canonical(payload)

        for record in self._records:
            if record["id"] == identifier:
                if _canonical(record["payload"]) == key:
                    return _detached(record)
                raise ValueError(
                    "conflicting payload for existing id %r" % (identifier,)
                )

        new_records = _detached(self._records)
        record = {
            "id": identifier,
            "payload": _detached(payload),
            "status": "pending",
        }
        new_records.append(record)
        self._write(new_records)
        self._records = new_records
        return _detached(record)

    def start_next(self):
        for record in self._records:
            if record["status"] == "running":
                raise RuntimeError("a record is already running")

        for index, record in enumerate(self._records):
            if record["status"] == "pending":
                new_records = _detached(self._records)
                new_records[index]["status"] = "running"
                self._write(new_records)
                self._records = new_records
                return _detached(new_records[index])

        return None

    def finish(self, identifier):
        index = None
        for position, record in enumerate(self._records):
            if record["id"] == identifier:
                index = position
                break
        if index is None:
            raise KeyError(identifier)

        status = self._records[index]["status"]
        if status == "completed":
            return _detached(self._records[index])
        if status != "running":
            raise ValueError(
                "cannot finish record %r in state %r" % (identifier, status)
            )

        new_records = _detached(self._records)
        new_records[index]["status"] = "completed"
        self._write(new_records)
        self._records = new_records
        return _detached(new_records[index])

    def snapshot(self):
        return _detached(self._records)

