class Decoder:
    _READ_LENGTH = 0
    _READ_PAYLOAD = 1

    def __init__(self, max_size=1024):
        if isinstance(max_size, bool) or not isinstance(max_size, int) or max_size < 0:
            raise ValueError("max_size must be a nonnegative int")
        self._max_size = max_size
        self._failed = False
        self._closed = False
        self._state = self._READ_LENGTH
        self._value = 0
        self._ndigits = 0
        self._target = 0
        self._payload = bytearray()

    def feed(self, data):
        if self._failed or self._closed:
            raise ValueError("decoder is not usable")
        if not isinstance(data, (bytes, bytearray)):
            raise TypeError("data must be bytes or bytearray")
        results = []
        for byte in data:
            if self._state == self._READ_LENGTH:
                self._length_byte(byte)
            else:
                self._payload_byte(byte, results)
        return results

    def finish(self):
        if self._failed or self._closed:
            raise ValueError("decoder is not usable")
        if self._state != self._READ_LENGTH or self._ndigits:
            self._failed = True
            raise ValueError("incomplete frame at end of stream")
        self._closed = True
        return None

    def _length_byte(self, byte):
        if 0x30 <= byte <= 0x39:
            if self._ndigits and self._value == 0:
                self._failed = True
                raise ValueError("leading zero in length")
            self._value = self._value * 10 + (byte - 0x30)
            self._ndigits += 1
            if self._value > self._max_size:
                self._failed = True
                raise ValueError("frame length exceeds max_size")
        elif byte == 0x3A:
            if not self._ndigits:
                self._failed = True
                raise ValueError("empty length")
            self._target = self._value
            self._state = self._READ_PAYLOAD
            self._payload = bytearray()
        else:
            self._failed = True
            raise ValueError("invalid length byte")

    def _payload_byte(self, byte, results):
        if len(self._payload) < self._target:
            self._payload.append(byte)
            return
        if byte != 0x2C:
            self._failed = True
            raise ValueError("missing frame terminator")
        try:
            text = self._payload.decode("utf-8")
        except UnicodeDecodeError:
            self._failed = True
            raise ValueError("invalid UTF-8 payload") from None
        results.append(text)
        self._state = self._READ_LENGTH
        self._value = 0
        self._ndigits = 0
        self._target = 0
        self._payload = bytearray()

