"""Core receipt summarization logic.

Only the Python standard library is used. Monetary sums are computed with
:class:`decimal.Decimal` so that no binary floating point error is introduced;
each customer total is rounded exactly once, using ``ROUND_HALF_UP``.
"""

from __future__ import annotations

import re
from decimal import ROUND_HALF_UP, Decimal

__all__ = ["summarize"]

# ASCII digits only, no sign, no exponent, no surrounding whitespace.
_AMOUNT_RE = re.compile(r"[0-9]+(?:\.[0-9]+)?")

_CENT = Decimal("0.01")
_ZERO = Decimal("0")

_VALID_STATUSES = ("paid", "void")


def _extract_customer(record: object) -> str:
    if not isinstance(record, dict):
        raise ValueError("receipt must be a mapping")
    if "customer" not in record:
        raise ValueError("missing customer field")
    customer = record["customer"]
    if not isinstance(customer, str):
        raise ValueError("customer must be a string")
    stripped = customer.strip()
    if not stripped:
        raise ValueError("customer must have a nonempty stripped value")
    return stripped


def _extract_amount(record: dict) -> Decimal:
    if "amount" not in record:
        raise ValueError("missing amount field")
    amount = record["amount"]
    if not isinstance(amount, str) or _AMOUNT_RE.fullmatch(amount) is None:
        raise ValueError("amount must be a string matching [0-9]+(?:\\.[0-9]+)?")
    return Decimal(amount)


def _extract_status(record: dict) -> str:
    if "status" not in record:
        raise ValueError("missing status field")
    status = record["status"]
    if status not in _VALID_STATUSES:
        raise ValueError('status must be exactly "paid" or "void"')
    return status


def summarize(records):
    """Summarize an iterable of receipt dictionaries.

    Every row (paid or void) is validated. Missing or invalid fields raise
    ``ValueError``. Only paid rows contribute to the totals; customers with
    only void rows are omitted. Equal customer names (after stripping
    surrounding whitespace) are combined. The returned list is sorted by
    customer using Python string ordering.
    """
    counts: dict[str, int] = {}
    totals: dict[str, Decimal] = {}

    for record in records:
        customer = _extract_customer(record)
        amount = _extract_amount(record)
        status = _extract_status(record)

        if status == "paid":
            counts[customer] = counts.get(customer, 0) + 1
            totals[customer] = totals.get(customer, _ZERO) + amount

    summary = []
    for customer in sorted(totals):
        rounded = totals[customer].quantize(_CENT, rounding=ROUND_HALF_UP)
        summary.append(
            {
                "customer": customer,
                "count": counts[customer],
                "total": str(rounded),
            }
        )
    return summary

