import re

_IDENTIFIER = re.compile(r'[A-Za-z_][A-Za-z0-9_]*\Z')


def _collapse_slashes(text):
    out = []
    prev_slash = False
    for ch in text:
        if ch == '/':
            if prev_slash:
                continue
            prev_slash = True
        else:
            prev_slash = False
        out.append(ch)
    return ''.join(out)


def _normalize(text):
    normalized = _collapse_slashes(text)
    while len(normalized) > 1 and normalized.endswith('/'):
        normalized = normalized[:-1]
    return normalized


def _split_segments(normalized):
    if normalized == '/':
        return []
    return normalized[1:].split('/')


class Router:
    def __init__(self):
        self.routes = []

    def add(self, pattern, handler):
        if not isinstance(pattern, str) or not pattern.startswith('/'):
            raise ValueError('pattern must be a string starting with "/"')
        if '?' in pattern or '#' in pattern:
            raise ValueError('pattern may not contain "?" or "#"')

        normalized = _normalize(pattern)
        segments = _split_segments(normalized)

        parsed = []
        seen = set()
        static_count = 0
        for segment in segments:
            if segment.startswith(':'):
                name = segment[1:]
                if not _IDENTIFIER.match(name):
                    raise ValueError('invalid parameter segment: %r' % segment)
                if name in seen:
                    raise ValueError('duplicate parameter name: %r' % name)
                seen.add(name)
                parsed.append((True, name))
            else:
                static_count += 1
                parsed.append((False, segment))

        for index, route in enumerate(self.routes):
            if route[0] == normalized:
                self.routes[index] = (normalized, parsed, static_count, handler)
                return
        self.routes.append((normalized, parsed, static_count, handler))

    def resolve(self, path):
        if not isinstance(path, str) or not path.startswith('/'):
            raise ValueError('path must be a string starting with "/"')

        cut = len(path)
        for marker in ('?', '#'):
            pos = path.find(marker)
            if pos != -1 and pos < cut:
                cut = pos
        candidate = _normalize(path[:cut])
        segments = _split_segments(candidate)

        best_handler = None
        best_params = None
        best_static = -1

        for _normalized, parsed, static_count, handler in self.routes:
            if len(parsed) != len(segments):
                continue
            if static_count <= best_static:
                continue

            params = {}
            matched = True
            for (is_param, expected), actual in zip(parsed, segments):
                if is_param:
                    if actual == '':
                        matched = False
                        break
                    params[expected] = actual
                elif expected != actual:
                    matched = False
                    break

            if matched:
                best_handler = handler
                best_params = params
                best_static = static_count

        if best_handler is None:
            raise KeyError(path)
        return best_handler, best_params

