        # 1.00 * 10 * 0.80 * 0.95 = 7.60
        self.assertEqual(pricing.price_line("1", 10, "gold"), Decimal("7.60"))

    def test_no_bulk_below_threshold(self):
        self.assertEqual(pricing.price_line("1", 9, "gold"), Decimal("7.20"))

    def test_round_half_up_once(self):
        # 0.005 rounds half up to 0.01 (contrast with banker's rounding).
        self.assertEqual(pricing.price_line("0.005", 1), Decimal("0.01"))
        self.assertEqual(pricing.price_line("0.015", 1), Decimal("0.02"))
        self.assertEqual(pricing.price_line("0.025", 1), Decimal("0.03"))

    def test_round_once_not_per_factor(self):
        # Rounding at each intermediate step would give 0.02 here.
        self.assertEqual(pricing.price_line("0.019", 1, "gold"), Decimal("0.02"))

