from decimal import Decimal

import pricing

REPORT_FORMAT = "customer-totals-v1"


def customer_totals(orders):
    """Aggregate rounded line amounts per customer, sorted by customer name.

    Each line is priced by ``pricing.price_line`` (looked up dynamically so a
    replaced function takes effect).  Orders with no items still produce a
    0.00 row for their customer.
    """
    totals = {}
    for order in orders:
        pricing.validate_tier(order["tier"])

        customer = order["customer"]
        subtotal = Decimal("0.00")
        for item in order["items"]:
            subtotal += pricing.price_line(
                item["unit_price"], item["quantity"], order["tier"]
            )
        totals[customer] = totals.get(customer, Decimal("0.00")) + subtotal

    return [
        {"customer": customer, "total": f"{totals[customer]:.2f}"}
        for customer in sorted(totals)
    ]

