"""Customer totals built from the same rounded lines as checkout."""

from decimal import Decimal

import pricing

REPORT_FORMAT = 'customer-totals-v1'


def customer_totals(orders):
    """Report ``[{'customer': ..., 'total': '0.00'}, ...]`` sorted by customer.

    Every order is priced with its own tier through :func:`pricing.price_line`,
    and per-customer totals aggregate those rounded line amounts.  An order
    whose items are empty still contributes a 0.00 row for its customer.
    Caller data is not mutated.
    """
    totals = {}
    for order in orders:
        customer = order['customer']
        tier = order.get('tier', 'bronze')
        # Validate the tier even for an order without items.
        pricing.tier_factor(tier)
        amount = Decimal('0.00')
        for item in order['items']:
            amount += Decimal(
                pricing.format_amount(
                    pricing.price_line(item['unit_price'], item['quantity'], tier)
                )
            )
        totals[customer] = totals.get(customer, Decimal('0.00')) + amount
    return [
        {'customer': customer, 'total': pricing.format_amount(total)}
        for customer, total in sorted(totals.items())
    ]

