files.router.py:
"""Route matching.

Public contract
---------------
``Router.add(pattern, handler)`` registers an opaque handler value;
``Router.resolve(path)`` returns ``(handler, params_dict)`` and never invokes the
handler.

* Both paths and patterns must be ``str`` starting with ``'/'``, otherwise
  ``ValueError`` is raised.
* Repeated ``'/'`` are collapsed and a trailing ``'/'`` is ignored (root stays
  ``'/'``).
* On ``resolve`` only, the first ``'?'`` or ``'#'`` and everything after it are
  discarded.  There is no URL decoding.
* Patterns may not contain ``'?'`` or ``'#'``.
* A parameter occupies a whole segment (``':user_id'``) and its name must be an
  ASCII identifier ``[A-Za-z_][A-Za-z0-9_]*``.  Parameter names in a single
  pattern must be unique.  Any segment starting with ``':'`` that is not a valid
  parameter is invalid.  Every other static segment character is a literal,
  never a regular expression.
* An invalid ``add`` raises ``ValueError`` and leaves all registered routes
  untouched.
* Matching requires the same number of segments; a parameter captures one
  nonempty segment.  Among all matches the route with the most static segments
  wins, ties keep registration order.
* Adding the same *normalized* pattern again replaces its handler while keeping
  its original position.  No match raises ``KeyError``.
* A root route is valid.  Returned ``params`` dicts are fresh on every call.
"""

import re

#: Whole-segment parameter, e.g. ``:user_id``.
_PARAM_RE = re.compile(r':([A-Za-z_][A-Za-z0-9_]*)\Z')


def _normalize_pattern(pattern):
    """Return the normalized segment tuple for *pattern* or raise ValueError."""
    if not isinstance(pattern, str) or not pattern.startswith('/'):
        raise ValueError('pattern must be a string starting with "/": %r' % (pattern,))
    if '?' in pattern or '#' in pattern:
        raise ValueError('pattern may not contain "?" or "#": %r' % (pattern,))

    segments = []
    seen = set()
    for raw in pattern.split('/'):
        if not raw:  # collapse repeated "/" and the trailing "/"
            continue
        if raw.startswith(':'):
            match = _PARAM_RE.fullmatch(raw)
            if match is None:
                raise ValueError('invalid parameter segment: %r' % (raw,))
            name = match.group(1)
            if name in seen:
                raise ValueError('duplicate parameter name: %r' % (name,))
            seen.add(name)
        segments.append(raw)
    return tuple(segments)


def _normalize_path(path):
    """Return the normalized segment tuple for *path* or raise ValueError."""
    if not isinstance(path, str) or not path.startswith('/'):
        raise ValueError('path must be a string starting with "/": %r' % (path,))

    # On resolve only: drop the first '?' or '#' and everything after it.
    for index, char in enumerate(path):
        if char == '?' or char == '#':
            path = path[:index]
            break

    return tuple(segment for segment in path.split('/') if segment)


def _param_name(segment):
    """Name of *segment* if it is a parameter, else ``None``."""
    if segment.startswith(':'):
        match = _PARAM_RE.fullmatch(segment)
        if match is not None:
            return match.group(1)
    return None


class Router:
    """Registers route patterns and resolves paths against them."""

    def __init__(self):
        # [(tuple_of_segments, handler), ...] in registration order.
        self.routes = []

    def add(self, pattern, handler):
        """Register *handler* for *pattern*, replacing an identical normalized pattern."""
        segments = _normalize_pattern(pattern)
        for index, (registered, _handler) in enumerate(self.routes):
            if registered == segments:
                self.routes[index] = (segments, handler)
                return
        self.routes.append((segments, handler))

    def resolve(self, path):
        """Return ``(handler, params)`` for *path* or raise ``KeyError``."""
        parts = _normalize_path(path)

        best = None
        best_static = -1
        for pattern, handler in self.routes:
            if len(pattern) != len(parts):
                continue
            params = {}
            static = 0
            for wanted, actual in zip(pattern, parts):
                name = _param_name(wanted)
                if name is None:
                    if wanted != actual:
                        break
                    static += 1
                else:
                    if not actual:
                        break
                    params[name] = actual
            else:
                # Most static segments wins; strict ">" keeps registration order on ties.
                if static > best_static:
                    best_static = static
                    best = (handler, params)

        if best is None:
            raise KeyError(path)
        return best[0], best[1]

