def _as_int(value, name):
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError(f"{name} must be an integer")
    return value


def coverage(intervals, start, end):
    start = _as_int(start, "start")
    end = _as_int(end, "end")
    if start > end:
        raise ValueError("start must be <= end")

    try:
        iterator = iter(intervals)
    except TypeError:
        raise ValueError("intervals must be a finite iterable")

    clipped = []
    for item in iterator:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise ValueError("each interval must be a two-element list or tuple")
        lo = _as_int(item[0], "interval lower bound")
        hi = _as_int(item[1], "interval upper bound")
        if lo > hi:
            raise ValueError("interval lower bound must be <= upper bound")
        clo = lo if lo > start else start
        chi = hi if hi < end else end
        if clo < chi:
            clipped.append((clo, chi))

    clipped.sort()

    merged = []
    for lo, hi in clipped:
        if merged and lo <= merged[-1][1]:
            if hi > merged[-1][1]:
                merged[-1][1] = hi
        else:
            merged.append([lo, hi])

    gaps = []
    cursor = start
    for lo, hi in merged:
        if lo > cursor:
            gaps.append([cursor, lo])
        cursor = hi
    if cursor < end:
        gaps.append([cursor, end])

    covered = sum(hi - lo for lo, hi in merged)
    return {"merged": merged, "gaps": gaps, "covered": covered}

