import re

_PARAM_RE = re.compile(r':([A-Za-z_][A-Za-z0-9_]*)\Z')


def _validate_start(value, what):
    if not isinstance(value, str) or not value.startswith('/'):
        raise ValueError(f'{what} must be a string starting with "/"')


def _normalize(s):
    while '//' in s:
        s = s.replace('//', '/')
    if len(s) > 1 and s.endswith('/'):
        s = s[:-1]
    return s


def _split(s):
    if s == '/':
        return []
    return s[1:].split('/')


def _strip_query(path):
    cut = len(path)
    for ch in ('?', '#'):
        idx = path.find(ch)
        if idx != -1 and idx < cut:
            cut = idx
    return path[:cut]


class Router:
    def __init__(self):
        self.routes = []
        self._index = {}

    def add(self, pattern, handler):
        _validate_start(pattern, 'pattern')
        if '?' in pattern or '#' in pattern:
            raise ValueError('pattern may not contain "?" or "#"')

        normalized = _normalize(pattern)
        compiled = []
        seen = set()
        static_count = 0
        for segment in _split(normalized):
            if segment.startswith(':'):
                match = _PARAM_RE.fullmatch(segment)
                if match is None:
                    raise ValueError(f'invalid parameter segment: {segment!r}')
                name = match.group(1)
                if name in seen:
                    raise ValueError(f'duplicate parameter name: {name!r}')
                seen.add(name)
                compiled.append((True, name))
            else:
                static_count += 1
                compiled.append((False, segment))

        entry = (normalized, compiled, static_count, handler)
        position = self._index.get(normalized)
        if position is None:
            self._index[normalized] = len(self.routes)
            self.routes.append(entry)
        else:
            self.routes[position] = entry

    def resolve(self, path):
        _validate_start(path, 'path')
        normalized = _normalize(_strip_query(path))
        parts = _split(normalized)

        best = None
        best_static = -1
        for _pattern, compiled, static_count, handler in self.routes:
            if len(compiled) != len(parts):
                continue
            params = {}
            matched = True
            for (is_param, value), actual in zip(compiled, parts):
                if is_param:
                    if actual == '':
                        matched = False
                        break
                    params[value] = actual
                elif value != actual:
                    matched = False
                    break
            if matched and static_count > best_static:
                best_static = static_count
                best = (handler, params)

        if best is None:
            raise KeyError(path)
        return best

