files.router.py:
"""Route matching for opaque handler values.

Public API:

    router = Router()
    router.add(pattern, handler)      -> None
    handler, params = router.resolve(path)

``add`` only registers; ``resolve`` never invokes the handler.  All path and
pattern normalisation rules are documented in README.md.
"""

import re

__all__ = ["Router"]

# A parameter segment is exactly ':' followed by an ASCII identifier.
_PARAM_SEGMENT_RE = re.compile(r":([A-Za-z_][A-Za-z0-9_]*)\Z")


def _check_path_string(value, what):
    """Every path/pattern must be a str starting with '/'."""
    if not isinstance(value, str):
        raise ValueError("%s must be a string, got %s" % (what, type(value).__name__))
    if not value.startswith("/"):
        raise ValueError("%s must start with '/': %r" % (what, value))
    return value


def _to_segments(value):
    """Collapse repeated '/' and ignore trailing '/' (root stays '/')."""
    return tuple(part for part in value.split("/") if part)


def _pattern_segments(pattern):
    """Validate ``pattern`` and return its normalised segments."""
    _check_path_string(pattern, "pattern")
    if "?" in pattern or "#" in pattern:
        raise ValueError("pattern may not contain '?' or '#': %r" % (pattern,))

    segments = _to_segments(pattern)
    seen = set()
    for segment in segments:
        if not segment.startswith(":"):
            # Static segments are literal text, never regular expressions.
            continue
        match = _PARAM_SEGMENT_RE.match(segment)
        if match is None:
            raise ValueError("invalid parameter segment: %r" % (segment,))
        name = match.group(1)
        if name in seen:
            raise ValueError("duplicate parameter name in pattern: %r" % (name,))
        seen.add(name)
    return segments


def _normal_key(segments):
    """Canonical form of a normalised pattern, used for replace-on-re-add."""
    return "/" + "/".join(segments)


def _strip_query_and_fragment(path):
    """Discard the first '?' or '#' and everything after it.  No URL decoding."""
    cut = len(path)
    for marker in "?#":
        found = path.find(marker)
        if found != -1 and found < cut:
            cut = found
    return path[:cut]


class Router:
    """Registers path patterns and resolves concrete paths to handlers."""

    def __init__(self):
        # Entries are (normalised_key, segments, static_segment_count, handler)
        # kept in registration order; a re-added pattern replaces its entry
        # in place so its original order is retained.
        self.routes = []

    def add(self, pattern, handler):
        """Register ``handler`` for ``pattern`` (validated before any change)."""
        segments = _pattern_segments(pattern)
        static_count = sum(1 for s in segments if not s.startswith(":"))
        key = _normal_key(segments)
        entry = (key, segments, static_count, handler)

        for index, existing in enumerate(self.routes):
            if existing[0] == key:
                self.routes[index] = entry
                return
        self.routes.append(entry)

    def resolve(self, path):
        """Return ``(handler, params)`` for ``path`` or raise ``KeyError``."""
        _check_path_string(path, "path")
        segments = _to_segments(_strip_query_and_fragment(path))

        best_static = -1
        best_handler = None
        best_params = None

        for _key, pattern_segments, static_count, handler in self.routes:
            if len(pattern_segments) != len(segments):
                continue
            params = {}
            for wanted, actual in zip(pattern_segments, segments):
                if wanted.startswith(":"):
                    if not actual:  # parameters capture one nonempty segment
                        break
                    params[wanted[1:]] = actual
                elif wanted != actual:
                    break
            else:
                # Ties in static-segment count keep registration order, which
                # this strict comparison preserves while scanning in order.
                if static_count > best_static:
                    best_static = static_count
                    best_handler = handler
                    best_params = params

        if best_static < 0:
            raise KeyError(path)
        return best_handler, best_params

