"""Randomised cross-check of Router.resolve against an independent model.

This file is an extra safety net on top of public_tests.py; it does not touch
the public API and uses the standard library only.
"""

import random
import re
import unittest

from router import Router

_MARKER = re.compile(r"[?#]")
_SLASH_RUN = re.compile(r"/{2,}")

STATIC_POOL = ["users", "new", "posts", "a.b", "p+q", "x_y", "v1", "[id]", "it's", "%20"]
PARAM_POOL = [":id", ":user_id", ":A1", ":_x", ":x9"]
VALUE_POOL = ["1", "abc", "x-y", "New", "a%20b", "~!", "0"]


def reference_segments(raw):
    """Independent normaliser: strip markers, collapse '/', drop trailing."""
    text = _MARKER.split(raw, maxsplit=1)[0]
    collapsed = _SLASH_RUN.sub("/", text)
    if collapsed == "/":
        return ()
    collapsed = collapsed.rstrip("/")
    if not collapsed:
        return ()
    return tuple(collapsed.split("/")[1:])


def reference_resolve(routes, path):
    """Reference matcher; routes is a list of (segments_tuple, handler)."""
    parts = reference_segments(path)
    candidates = []
    for index, (pattern, handler) in enumerate(routes):
        if len(pattern) != len(parts):
            continue
        params = {}
        matched = True
        for wanted, actual in zip(pattern, parts):
            if wanted.startswith(":"):
                if not actual:
                    matched = False
                    break
                params[wanted[1:]] = actual
            elif wanted != actual:
                matched = False
                break
        if matched:
            static_count = len([s for s in pattern if not s.startswith(":")])
            candidates.append((static_count, -index, handler, params))
    if not candidates:
        raise KeyError(path)
    candidates.sort(reverse=True, key=lambda item: (item[0], item[1]))
    return candidates[0][2], candidates[0][3]


def random_pattern(rng):
    segments = []
    used = set()
    for _ in range(rng.randint(0, 3)):
        if rng.random() < 0.45:
            segments.append(rng.choice(STATIC_POOL))
        else:
            name = rng.choice(PARAM_POOL)
            if name in used:
                continue
            used.add(name)
            segments.append(name)
    noise = "//" if rng.random() < 0.25 else ""
    trailing = rng.choice(["", "/", "//"]) if rng.random() < 0.4 else ""
    return "/" + noise + "/".join(segments) + trailing


def path_from_segments(rng, segments):
    parts = []
    for segment in segments:
        parts.append(rng.choice(VALUE_POOL) if segment.startswith(":") else segment)
    text = "/" + "/".join(parts)
    if rng.random() < 0.15:
        text += rng.choice(["/", "//"])
    if rng.random() < 0.25:
        text += rng.choice(["?a=1", "#frag", "?a=1#frag", "#frag?a=1"])
    return text


class FuzzTests(unittest.TestCase):
    def test_resolve_matches_reference_model(self):
        rng = random.Random(20260929)
        for trial in range(300):
            router = Router()
            reference = []
            for _ in range(rng.randint(1, 7)):
                pattern = random_pattern(rng)
                handler = "h%d" % rng.randrange(1000)
                segments = reference_segments(pattern)
                router.add(pattern, handler)
                entry = (segments, handler)
                for index, existing in enumerate(reference):
                    if existing[0] == segments:
                        reference[index] = entry
                        break
                else:
                    reference.append(entry)

            paths = [path_from_segments(rng, entry[0]) for entry in reference]
            paths += [
                "/",
                "//",
                "/unknown",
                "/unknown/deep/path",
                "/users/new?q=1",
                "/users/#f",
            ]

            for path in paths:
                expected_error = None
                try:
                    expected = reference_resolve(reference, path)
                except KeyError:
                    expected = None
                    expected_error = KeyError
                if expected_error is None:
                    self.assertEqual(
                        router.resolve(path), expected,
                        "trial %d path %r routes %r" % (trial, path, reference),
                    )
                else:
                    with self.assertRaises(KeyError):
                        router.resolve(path)

    def test_returned_params_are_isolated(self):
        rng = random.Random(7)
        router = Router()
        router.add("/u/:id/p/:page", "h")
        seen = []
        for _ in range(50):
            first = router.resolve("/u/%d/p/%d" % (rng.randrange(9), rng.randrange(9)))[1]
            first["injected"] = True
            second = router.resolve("/u/2/p/3")[1]
            self.assertNotIn("injected", second)
            seen.append(second)
        self.assertEqual(seen[-1], {"id": "2", "page": "3"})


if __name__ == "__main__":
    unittest.main()

