"""Command line interface for receipt summaries."""

import csv
import io
import json
import os
import sys
import tempfile

from .model import summarize


def _read_records(path):
    with open(path, "r", encoding="utf-8") as handle:
        for line in handle:
            if line.strip() == "":
                continue
            yield json.loads(line)


def _render_csv(summary):
    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(["customer", "count", "total"])
    for row in summary:
        writer.writerow([row["customer"], row["count"], row["total"]])
    return buffer.getvalue()


def main(argv=None):
    args = list(sys.argv[1:] if argv is None else argv)
    if len(args) != 2:
        sys.stderr.write("usage: python -m receipt_tools.cli INPUT.jsonl OUTPUT.csv\n")
        return 1

    input_path, output_path = args

    try:
        summary = summarize(_read_records(input_path))
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        sys.stderr.write("error: {0}\n".format(exc))
        return 1

    content = _render_csv(summary)

    directory = os.path.dirname(os.path.abspath(output_path))
    try:
        fd, tmp_path = tempfile.mkstemp(dir=directory, suffix=".tmp")
        try:
            with os.fdopen(fd, "w", encoding="utf-8", newline="") as handle:
                handle.write(content)
            os.replace(tmp_path, output_path)
        except BaseException:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
            raise
    except OSError as exc:
        sys.stderr.write("error: {0}\n".format(exc))
        return 1

    return 0


if __name__ == "__main__":
    raise SystemExit(main())

