"""Normalize half-open interval coverage.

Public API:
    coverage(intervals, start, end) -> dict

See README.md for the full contract.
"""

__all__ = ["coverage"]


def _is_integer(value):
    """True for Python integers, explicitly excluding bool."""
    return isinstance(value, int) and not isinstance(value, bool)


def _validate_bound(value, name):
    if not _is_integer(value):
        raise ValueError(f"{name} must be an integer")
    return value


def coverage(intervals, start, end):
    """Compute the normalized coverage of half-open intervals in a window.

    Returns ``{'merged': [[lo, hi], ...], 'gaps': [[lo, hi], ...],
    'covered': int}``.
    """
    start = _validate_bound(start, "start")
    end = _validate_bound(end, "end")
    if start > end:
        raise ValueError("start must be <= end")

    # Materialize the finite iterable once so it can be traversed safely.
    try:
        items = list(intervals)
    except TypeError:
        raise ValueError("intervals must be a finite iterable") from None

    # Validate *every* interval up front, even ones wholly outside the window.
    normalized = []
    for item in items:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise ValueError("each interval must be a two-element list or tuple")
        lo, hi = item
        if not _is_integer(lo) or not _is_integer(hi):
            raise ValueError("interval endpoints must be integers")
        if lo > hi:
            raise ValueError("interval lower bound must be <= upper bound")
        normalized.append((lo, hi))

    if start == end:
        return {"merged": [], "gaps": [], "covered": 0}

    # Clip each valid interval to [start, end), dropping empty results.
    clipped = []
    for lo, hi in normalized:
        clo = lo if lo > start else start
        chi = hi if hi < end else end
        if clo < chi:
            clipped.append((clo, chi))

    clipped.sort()

    # Merge overlapping *or touching* intervals.
    merged = []
    for lo, hi in clipped:
        if merged and lo <= merged[-1][1]:
            if hi > merged[-1][1]:
                merged[-1][1] = hi
        else:
            merged.append([lo, hi])

    # Complement within the window.
    gaps = []
    cursor = start
    for lo, hi in merged:
        if cursor < lo:
            gaps.append([cursor, lo])
        cursor = hi
    if cursor < end:
        gaps.append([cursor, end])

    # Length is computed from merged spans, never by enumeration.
    covered = sum(hi - lo for lo, hi in merged)

    return {"merged": merged, "gaps": gaps, "covered": covered}

