import random
import unittest

from coverage import coverage


class Contract(unittest.TestCase):
    def test_empty_window(self):
        self.assertEqual(
            coverage([[1, 5], [-3, -1]], 4, 4),
            {"merged": [], "gaps": [], "covered": 0},
        )

    def test_clip_nothing_inside(self):
        self.assertEqual(
            coverage([[10, 20]], 0, 5),
            {"merged": [], "gaps": [[0, 5]], "covered": 0},
        )

    def test_touching_merge(self):
        self.assertEqual(
            coverage([[0, 2], [2, 4]], 0, 10),
            {"merged": [[0, 4]], "gaps": [[4, 10]], "covered": 4},
        )

    def test_overlap_and_gaps(self):
        self.assertEqual(
            coverage([[1, 3], [5, 7], [2, 6]], 0, 10),
            {"merged": [[1, 7]], "gaps": [[0, 1], [7, 10]], "covered": 6},
        )

    def test_duplicates(self):
        self.assertEqual(
            coverage([[1, 3], [1, 3]], 0, 5),
            {"merged": [[1, 3]], "gaps": [[0, 1], [3, 5]], "covered": 2},
        )

    def test_negative_and_huge(self):
        big = 10 ** 100
        self.assertEqual(
            coverage([[-big, 0], [0, big]], -big, big),
            {"merged": [[-big, big]], "gaps": [], "covered": 2 * big},
        )

    def test_generator_input(self):
        gen = (x for x in [[0, 1], [3, 5]])
        self.assertEqual(
            coverage(gen, 0, 5),
            {"merged": [[0, 1], [3, 5]], "gaps": [[1, 3]], "covered": 3},
        )

    def test_no_mutation(self):
        original = [[0, 2], [1, 5]]
        snapshot = [list(x) for x in original]
        coverage(original, 0, 5)
        self.assertEqual(original, snapshot)
        self.assertIsInstance(original[0], list)

    def test_tuple_intervals_ok(self):
        self.assertEqual(
            coverage(((0, 1), (2, 3)), 0, 3),
            {"merged": [[0, 1], [2, 3]], "gaps": [[1, 2]], "covered": 2},
        )

    def test_invalid_outside_window_still_raises(self):
        # A valid interval outside the window is ignored, not an error.
        self.assertEqual(
            coverage([[100, 200]], 0, 5),
            {"merged": [], "gaps": [[0, 5]], "covered": 0},
        )
        with self.assertRaises(ValueError):
            coverage([[200, 100]], 0, 5)  # invalid, wholly outside

    def test_invalid_bounds(self):
        for bad in (True, 1.0, "1", None):
            with self.assertRaises(ValueError):
                coverage([], bad, 5)
            with self.assertRaises(ValueError):
                coverage([], 0, bad)
        with self.assertRaises(ValueError):
            coverage([], 5, 0)

    def test_invalid_items(self):
        for bad in ([1], [1, 2, 3], 5, "ab", (1,), {1: 2}):
            with self.assertRaises(ValueError):
                coverage([bad], 0, 5)
        with self.assertRaises(ValueError):
            coverage([True, 2], 0, 5)
        with self.assertRaises(ValueError):
            coverage([1, True], 0, 5)

    def test_non_iterable(self):
        with self.assertRaises(ValueError):
            coverage(123, 0, 5)


class RandomCheck(unittest.TestCase):
    def test_random_against_brute_force(self):
        rng = random.Random(1234)
        for _ in range(500):
            start = rng.randint(-20, 20)
            end = rng.randint(start, 20)
            intervals = []
            for _ in range(rng.randint(0, 6)):
                lo = rng.randint(-25, 25)
                hi = rng.randint(lo, 25)
                intervals.append((lo, hi))
            result = coverage(list(intervals), start, end)

            members = set(range(start, end))
            covered_set = set()
            for lo, hi in intervals:
                covered_set |= members & set(range(lo, hi))
            merged = []
            for x in range(start, end):
                if x in covered_set:
                    if merged and merged[-1][1] == x:
                        merged[-1][1] = x + 1
                    else:
                        merged.append([x, x + 1])
            gaps = []
            for x in range(start, end):
                if x not in covered_set:
                    if gaps and gaps[-1][1] == x:
                        gaps[-1][1] = x + 1
                    else:
                        gaps.append([x, x + 1])
            self.assertEqual(
                result,
                {
                    "merged": merged,
                    "gaps": gaps,
                    "covered": len(covered_set),
                },
            )


if __name__ == "__main__":
    unittest.main()

