"""Route matching with static-over-parameter precedence.

Public API:
    Router.add(pattern, handler)
    Router.resolve(path) -> (handler, params)

See README.md for the full contract.
"""

import re

# A whole segment that is a parameter: ':' followed by an ASCII identifier.
_PARAM_RE = re.compile(r"^:([A-Za-z_][A-Za-z0-9_]*)\Z")


def _normalize(value):
    """Collapse repeated '/' and drop trailing '/' (root stays '/')."""
    parts = [p for p in value.split("/") if p != ""]
    if not parts:
        return "/"
    return "/" + "/".join(parts)


def _segments(normalized):
    """Split a normalized path/pattern into its segments (root -> [])."""
    if normalized == "/":
        return []
    return normalized[1:].split("/")


class Router:
    def __init__(self):
        # Each route: [normalized_pattern, compiled_segments, static_count, handler]
        # compiled_segments is a list of (is_param, name_or_literal).
        self.routes = []

    def add(self, pattern, handler):
        if not isinstance(pattern, str) or not pattern.startswith("/"):
            raise ValueError("pattern must be a string starting with '/'")
        if "?" in pattern or "#" in pattern:
            raise ValueError("pattern may not contain '?' or '#'")

        normalized = _normalize(pattern)
        compiled = []
        seen = set()
        static_count = 0

        for segment in _segments(normalized):
            if segment.startswith(":"):
                match = _PARAM_RE.match(segment)
                if match is None:
                    raise ValueError("invalid parameter segment: %r" % (segment,))
                name = match.group(1)
                if name in seen:
                    raise ValueError("duplicate parameter name: %r" % (name,))
                seen.add(name)
                compiled.append((True, name))
            else:
                static_count += 1
                compiled.append((False, segment))

        # Validation succeeded; now it is safe to mutate the registry.
        for route in self.routes:
            if route[0] == normalized:
                route[3] = handler  # replace handler, keep order
                return
        self.routes.append([normalized, compiled, static_count, handler])

    def resolve(self, path):
        if not isinstance(path, str) or not path.startswith("/"):
            raise ValueError("path must be a string starting with '/'")
        original = path

        # On resolve only: discard the first '?' or '#' and everything after it.
        cut = len(path)
        for marker in ("?", "#"):
            index = path.find(marker)
            if index != -1 and index < cut:
                cut = index
        normalized = _normalize(path[:cut])
        parts = _segments(normalized)

        best = None
        best_static = -1

        for route in self.routes:
            compiled, static_count, handler = route[1], route[2], route[3]
            if len(compiled) != len(parts):
                continue

            params = {}
            for (is_param, value), actual in zip(compiled, parts):
                if is_param:
                    if actual == "":
                        break
                    params[value] = actual
                elif value != actual:
                    break
            else:
                # First route with the highest static count wins (ties keep order).
                if static_count > best_static:
                    best_static = static_count
                    best = (handler, params)

        if best is None:
            raise KeyError(original)
        return best

