"""Normalize half-open interval coverage over a requested window.

Public API:
    coverage(intervals, start, end) -> {
        'merged': [[lo, hi], ...],
        'gaps': [[lo, hi], ...],
        'covered': int,
    }

Intervals are treated as half-open [lo, hi).  They are validated, clipped to
[start, end), sorted, and merged when they overlap or merely touch.  ``gaps``
is the sorted nonempty complement of ``merged`` inside [start, end).
"""


def _require_int(value, name):
    """Return *value* if it is a real integer; otherwise raise ValueError.

    ``bool`` is a subclass of ``int`` but is explicitly rejected because the
    contract states booleans are not valid integers.
    """
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError(
            "{} must be an integer, got {!r}".format(name, value)
        )
    return value


def coverage(intervals, start, end):
    start = _require_int(start, "start")
    end = _require_int(end, "end")
    if start > end:
        raise ValueError("start must be less than or equal to end")

    try:
        iterator = iter(intervals)
    except TypeError:
        raise ValueError("intervals must be a finite iterable") from None

    # Validate every item before it is clipped so that malformed intervals are
    # rejected even when they lie wholly outside [start, end).  We never touch
    # the caller's sequences and never trust their identity for output.
    clipped = []
    for index, item in enumerate(iterator):
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise ValueError(
                "interval at index {} must be a two-element list or tuple".format(
                    index
                )
            )
        lo = _require_int(item[0], "interval[{}].lo".format(index))
        hi = _require_int(item[1], "interval[{}].hi".format(index))
        if lo > hi:
            raise ValueError(
                "interval at index {} has lo > hi".format(index)
            )

        if lo < start:
            lo = start
        if hi > end:
            hi = end
        if lo < hi:  # ignore empty clipped intervals and empty input ranges
            clipped.append([lo, hi])

    clipped.sort(key=lambda pair: (pair[0], pair[1]))

    merged = []
    for lo, hi in clipped:
        if merged and lo <= merged[-1][1]:
            # Overlapping or touching half-open intervals: [a, b) + [b, c).
            if hi > merged[-1][1]:
                merged[-1][1] = hi
        else:
            merged.append([lo, hi])

    gaps = []
    cursor = start
    for lo, hi in merged:
        if lo > cursor:
            gaps.append([cursor, lo])
        cursor = hi
    if cursor < end:
        gaps.append([cursor, end])

    covered = sum(hi - lo for lo, hi in merged)

    return {"merged": merged, "gaps": gaps, "covered": covered}

