"""Command line interface for receipt summarization."""

from __future__ import annotations

import csv
import json
import os
import sys
import tempfile

from .model import summarize


def _read_records(path):
    records = []
    with open(path, "r", encoding="utf-8") as handle:
        for line in handle:
            stripped = line.strip()
            if not stripped:
                continue
            records.append(json.loads(stripped))
    return records


def _write_summary(path, rows):
    directory = os.path.dirname(os.path.abspath(path))
    fd, tmp_path = tempfile.mkstemp(dir=directory, suffix=".tmp")
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="") as handle:
            writer = csv.writer(handle, lineterminator="\n")
            writer.writerow(["customer", "count", "total"])
            for row in rows:
                writer.writerow([row["customer"], row["count"], row["total"]])
        os.replace(tmp_path, path)
    except OSError:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise


def main(argv=None):
    argv = list(sys.argv[1:] if argv is None else argv)
    if len(argv) != 2:
        print("usage: python -m receipt_tools.cli INPUT.jsonl OUTPUT.csv", file=sys.stderr)
        return 2

    input_path, output_path = argv
    try:
        records = _read_records(input_path)
        rows = summarize(records)
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1

    try:
        _write_summary(output_path, rows)
    except OSError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

