"""Core receipt summarization logic."""

from __future__ import annotations

import re
from decimal import Decimal, ROUND_HALF_UP

_AMOUNT_RE = re.compile(r"\A[0-9]+(?:\.[0-9]+)?\Z")
_TWO_PLACES = Decimal("0.01")


def summarize(records):
    """Summarize an iterable of receipt dicts.

    Returns a list of ``{"customer": str, "count": int, "total": str}`` dicts
    sorted by customer (Python string order). Only ``paid`` rows contribute.
    """
    totals = {}
    counts = {}

    for record in records:
        try:
            customer = record["customer"]
            amount = record["amount"]
            status = record["status"]
        except (TypeError, KeyError) as exc:
            raise ValueError(f"receipt missing required field: {exc}") from exc

        if not isinstance(customer, str):
            raise ValueError("customer must be a string")
        customer = customer.strip()
        if not customer:
            raise ValueError("customer must be a nonempty string")

        if not isinstance(amount, str) or not _AMOUNT_RE.match(amount):
            raise ValueError(f"invalid amount: {amount!r}")

        if status not in ("paid", "void"):
            raise ValueError(f"invalid status: {status!r}")

        if status != "paid":
            continue

        if customer not in totals:
            totals[customer] = Decimal(0)
            counts[customer] = 0
        totals[customer] += Decimal(amount)
        counts[customer] += 1

    result = []
    for customer in sorted(totals):
        total = totals[customer].quantize(_TWO_PLACES, rounding=ROUND_HALF_UP)
        result.append(
            {"customer": customer, "count": counts[customer], "total": str(total)}
        )
    return result

files.coverage.py:
"""Normalize half-open interval coverage over an integer window.

Public API
----------
``coverage(intervals, start, end)`` returns exactly::

    {"merged": [[lo, hi], ...], "gaps": [[lo, hi], ...], "covered": int}

Intervals are half-open ``[lo, hi)`` with integer endpoints, clipped to the
requested window ``[start, end)``.  Empty clipped pieces are dropped, the
remaining pieces are sorted and merged when they overlap *or touch*, and the
returned gaps are the nonempty complement of ``merged`` inside the window.
Only integer arithmetic is used, so arbitrarily large values are supported
without enumerating individual integers.
"""

from __future__ import annotations

__all__ = ["coverage"]


def _as_int(value, label):
    """Return *value* if it is a genuine integer, else raise ``ValueError``.

    ``bool`` is rejected even though it subclasses ``int``.
    """
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError(f"{label} must be an integer, got {type(value).__name__}")
    return value


def _clip(intervals, start, end):
    """Validate *intervals* and return the nonempty pieces inside [start, end).

    Every element is validated, even when it lies wholly outside the window,
    and the caller's objects are only read, never modified.
    """
    try:
        iterator = iter(intervals)
    except TypeError:
        raise ValueError(
            "intervals must be a finite iterable of two-element lists/tuples"
        ) from None

    pairs = []
    for index, item in enumerate(iterator):
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise ValueError(
                f"interval #{index} must be a two-element list or tuple, "
                f"got {type(item).__name__}"
            )
        lo = _as_int(item[0], f"interval #{index} lower bound")
        hi = _as_int(item[1], f"interval #{index} upper bound")
        if lo > hi:
            raise ValueError(
                f"interval #{index} lower bound {lo} exceeds upper bound {hi}"
            )
        if lo < start:
            lo = start
        if hi > end:
            hi = end
        if lo < hi:
            pairs.append((lo, hi))
    return pairs


def coverage(intervals, start, end):
    """Clip, sort, merge and complement half-open integer intervals.

    ``intervals`` is any finite iterable of two-element lists/tuples
    ``[lo, hi]`` with ``lo <= hi``; ``start <= end`` are the window bounds.
    Invalid input raises ``ValueError``.  The caller's iterable and its
    elements are never mutated or reordered.
    """
    start = _as_int(start, "start")
    end = _as_int(end, "end")
    if start > end:
        raise ValueError(f"start ({start}) must be <= end ({end})")

    merged = []
    for lo, hi in sorted(_clip(intervals, start, end)):
        if merged and lo <= merged[-1][1]:
            # Overlapping or exactly touching: extend the previous piece.
            if hi > merged[-1][1]:
                merged[-1][1] = hi
        else:
            merged.append([lo, hi])

    gaps = []
    cursor = start
    for lo, hi in merged:
        if cursor < lo:
            gaps.append([cursor, lo])
        cursor = hi
    if cursor < end:
        gaps.append([cursor, end])

    covered = sum(hi - lo for lo, hi in merged)
    return {"merged": merged, "gaps": gaps, "covered": covered}

