from decimal import Decimal, ROUND_HALF_UP

import pricing

_CENT = Decimal('0.01')

REPORT_FORMAT = 'customer-totals-v1'


def customer_totals(orders):
    totals = {}
    for order in orders:
        customer = order['customer']
        tier = order.get('tier', 'bronze')
        subtotal = Decimal('0.00')
        for item in order['items']:
            subtotal += pricing.price_line(item['unit_price'], item['quantity'], tier)
        totals[customer] = totals.get(customer, Decimal('0.00')) + subtotal
    return [
        {
            'customer': customer,
            'total': format(
                totals[customer].quantize(_CENT, rounding=ROUND_HALF_UP), 'f'
            ),
        }
        for customer in sorted(totals)
    ]

