"""Route matching.

Public API:
    Router.add(pattern, handler)  -> register an opaque handler
    Router.resolve(path)          -> (handler, params_dict)

See README.md for the full contract.
"""

import re

# A parameter is a whole segment of the form ':<identifier>'.
_PARAM_RE = re.compile(r"^:([A-Za-z_][A-Za-z0-9_]*)$")


def _strip_query(path):
    """Discard the first '?' or '#' and everything after it."""
    end = len(path)
    for marker in ("?", "#"):
        idx = path.find(marker)
        if idx != -1 and idx < end:
            end = idx
    return path[:end]


def _normalize(path):
    """Collapse repeated '/' and ignore trailing '/' (root -> []).

    Returns the path as a list of non-empty segments.
    """
    return [segment for segment in path.split("/") if segment != ""]


def _validate_pattern(pattern):
    """Validate a pattern and return its normalized list of segments.

    Raises ValueError for any violation.  Never mutates the router.
    """
    if not isinstance(pattern, str):
        raise ValueError("pattern must be a string")
    if not pattern.startswith("/"):
        raise ValueError("pattern must start with '/'")
    if "?" in pattern or "#" in pattern:
        raise ValueError("pattern may not contain '?' or '#'")

    segments = _normalize(pattern)
    seen = set()
    for segment in segments:
        if segment.startswith(":"):
            match = _PARAM_RE.match(segment)
            if match is None:
                raise ValueError("invalid parameter segment: %r" % (segment,))
            name = match.group(1)
            if name in seen:
                raise ValueError("duplicate parameter name: %r" % (name,))
            seen.add(name)
    return segments


class Router:
    def __init__(self):
        # Each entry is (normalized_segments_tuple, handler).  The list order
        # is the registration order and is used for tie-breaking.
        self.routes = []

    def add(self, pattern, handler):
        # Validate fully before touching self.routes so an invalid add leaves
        # every registered route exactly as it was.
        segments = _validate_pattern(pattern)
        key = tuple(segments)

        for index, (existing_key, _existing_handler) in enumerate(self.routes):
            if existing_key == key:
                # Same normalized pattern: replace handler, keep order.
                self.routes[index] = (key, handler)
                return

        self.routes.append((key, handler))

    def resolve(self, path):
        if not isinstance(path, str):
            raise ValueError("path must be a string")
        if not path.startswith("/"):
            raise ValueError("path must start with '/'")

        path = _strip_query(path)
        parts = _normalize(path)

        found = False
        best_static = -1
        best_handler = None
        best_params = None

        for segments, handler in self.routes:
            if len(segments) != len(parts):
                continue

            static_count = 0
            params = {}
            matched = True
            for pattern_segment, actual in zip(segments, parts):
                if pattern_segment.startswith(":"):
                    # A whole segment is captured; normalization guarantees it
                    # is nonempty.
                    params[pattern_segment[1:]] = actual
                else:
                    if pattern_segment != actual:
                        matched = False
                        break
                    static_count += 1

            if matched and static_count > best_static:
                found = True
                best_static = static_count
                best_handler = handler
                best_params = params

        if not found:
            raise KeyError(path)

        return best_handler, best_params

