"""Customer reporting built on the same shared pricing formula as checkout.

Each line is priced by ``pricing.price_line`` at call time, so replacing that
function changes reports and checkout together.
"""

from decimal import Decimal, ROUND_HALF_UP, localcontext

import pricing

REPORT_FORMAT = "customer-totals-v1"

_CENT = Decimal("0.01")
_AGGREGATE_PRECISION = 60


def _check_tier(tier):
    """Validate a tier through pricing, which owns that rule."""
    validator = getattr(pricing, "validate_tier", None)
    if validator is not None:
        validator(tier)


def _to_money(amount):
    """Quantize a price_line() result to 0.01 (ROUND_HALF_UP) as a Decimal."""
    quantizer = getattr(pricing, "quantize_money", None)
    if quantizer is not None:
        return quantizer(amount)
    if not isinstance(amount, Decimal):
        amount = Decimal(str(amount))
    return amount.quantize(_CENT, rounding=ROUND_HALF_UP)


def _price_line(unit_price, quantity, tier):
    """Route one line through pricing.price_line, resolved at call time."""
    return _to_money(pricing.price_line(unit_price, quantity, tier))


def customer_totals(orders):
    """Aggregate rounded line amounts per customer, sorted by customer.

    An order with no items still contributes a 0.00 row.  Caller dictionaries
    and lists are never mutated.
    """
    with localcontext() as ctx:
        ctx.prec = _AGGREGATE_PRECISION
        totals = {}
        for order in orders:
            tier = order.get("tier", "bronze")
            _check_tier(tier)
            customer = order["customer"]
            running = totals.get(customer, Decimal("0.00"))
            for item in order.get("items") or ():
                running += _price_line(item.get("unit_price"), item.get("quantity"), tier)
            totals[customer] = running
        rows = [
            {"customer": customer,
             "total": str(amount.quantize(_CENT, rounding=ROUND_HALF_UP))}
            for customer, amount in totals.items()
        ]
    rows.sort(key=lambda row: row["customer"])
    return rows

