"""Single owner of the pricing formula shared by checkout and reports."""

import re
from decimal import Decimal, ROUND_HALF_UP, localcontext

_CENT = Decimal('0.01')
_MONEY_RE = re.compile(r'[0-9]+(?:\.[0-9]+)?')
_TIER_FACTORS = {
    'bronze': Decimal('1'),
    'silver': Decimal('0.90'),
    'gold': Decimal('0.80'),
}
_BULK_QUANTITY = 10
_BULK_FACTOR = Decimal('0.95')
_PRECISION = 60


def _valid_money(value):
    return (
        isinstance(value, str)
        and not isinstance(value, bool)
        and _MONEY_RE.fullmatch(value) is not None
    )


def _valid_quantity(value):
    return (
        isinstance(value, int)
        and not isinstance(value, bool)
        and value >= 0
    )


def _tier_factor(tier):
    try:
        return _TIER_FACTORS[tier]
    except (KeyError, TypeError):
        raise ValueError('invalid tier: {!r}'.format(tier))


def price_line(unit_price, quantity, tier='bronze'):
    """Return the rounded line amount as a Decimal quantized to 0.01."""
    if not _valid_money(unit_price):
        raise ValueError('invalid unit_price: {!r}'.format(unit_price))
    if not _valid_quantity(quantity):
        raise ValueError('invalid quantity: {!r}'.format(quantity))
    factor = _tier_factor(tier)

    with localcontext() as ctx:
        ctx.prec = _PRECISION
        amount = Decimal(unit_price) * quantity * factor
        if quantity >= _BULK_QUANTITY:
            amount = amount * _BULK_FACTOR
        return amount.quantize(_CENT, rounding=ROUND_HALF_UP)

