"""Normalize half-open interval coverage inside a requested window.

Public API: :func:`coverage`.  See ``README.md`` for the full contract.
"""

from __future__ import annotations

__all__ = ["coverage"]


def _require_int(value, name):
    """Return *value* when it is a true integer, else raise ``ValueError``."""
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError(f"{name} must be an integer, got {value!r}")
    return value


def _require_interval(item, index):
    """Validate one raw interval and return it as an ``(lo, hi)`` tuple."""
    if not isinstance(item, (list, tuple)) or len(item) != 2:
        raise ValueError(
            f"intervals[{index}] must be a two-element list or tuple, got {item!r}"
        )
    lo = _require_int(item[0], f"intervals[{index}][0]")
    hi = _require_int(item[1], f"intervals[{index}][1]")
    if lo > hi:
        raise ValueError(f"intervals[{index}] has lo > hi: {item!r}")
    return lo, hi


def coverage(intervals, start, end):
    """Clip half-open intervals to ``[start, end)`` and describe the result.

    Returns ``{'merged': [[lo, hi], ...], 'gaps': [[lo, hi], ...],
    'covered': integer_length}`` where ``merged`` holds the sorted, merged
    (overlapping *or* touching) clipped intervals, ``gaps`` the nonempty
    complement inside the window, and ``covered`` the total integer length.

    Invalid input raises ``ValueError``; every item is validated even when it
    lies wholly outside the window.  The caller's objects are never mutated.
    """
    start = _require_int(start, "start")
    end = _require_int(end, "end")
    if start > end:
        raise ValueError(f"start must be <= end, got start={start!r} end={end!r}")

    try:
        iterator = iter(intervals)
    except TypeError:
        raise ValueError(f"intervals must be a finite iterable, got {intervals!r}") from None

    clipped = []
    for index, item in enumerate(iterator):
        lo, hi = _require_interval(item, index)
        lo = max(lo, start)
        hi = min(hi, end)
        if lo < hi:
            clipped.append((lo, hi))

    clipped.sort()

    merged = []
    for lo, hi in clipped:
        if merged and lo <= merged[-1][1]:
            if hi > merged[-1][1]:
                merged[-1][1] = hi
        else:
            merged.append([lo, hi])

    gaps = []
    cursor = start
    for lo, hi in merged:
        if lo > cursor:
            gaps.append([cursor, lo])
        cursor = hi
    if cursor < end:
        gaps.append([cursor, end])

    covered = 0
    for lo, hi in merged:
        covered += hi - lo
    return {"merged": merged, "gaps": gaps, "covered": covered}

