"""Extra contract checks for :mod:`coverage`.

These are my own tests, kept separate from the frozen ``public_tests.py``.
Run with ``python -m unittest discover`` (or ``python -m tests.test_coverage_extra``).
"""

import copy
import os
import random
import sys
import unittest

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from coverage import coverage  # noqa: E402  (local module, path set above)


def brute_force(intervals, start, end):
    """Reference result computed by enumerating integers (small ranges only)."""
    points = set()
    for lo, hi in intervals:
        for value in range(max(lo, start), min(hi, end)):
            points.add(value)
    merged, gaps = [], []
    x = start
    while x < end:
        y = x
        while y < end and (y in points):
            y += 1
        if y > x:
            merged.append([x, y])
        else:
            while y < end and (y not in points):
                y += 1
            gaps.append([x, y])
        x = y
    return {"merged": merged, "gaps": gaps, "covered": len(points)}


class MergeAndClipTests(unittest.TestCase):
    def test_public_smoke_case(self):
        self.assertEqual(
            coverage([[3, 5], [-2, 2], [2, 4]], 0, 7),
            {"merged": [[0, 5]], "gaps": [[5, 7]], "covered": 5},
        )

    def test_touching_intervals_merge(self):
        self.assertEqual(coverage([[0, 2], [2, 4]], 0, 4),
                         {"merged": [[0, 4]], "gaps": [], "covered": 4})
        self.assertEqual(coverage([[2, 4], [0, 2]], 0, 4)["merged"], [[0, 4]])

    def test_unsorted_overlapping_and_duplicated(self):
        result = coverage([[5, 7], [0, 2], [1, 3], [0, 2]], 0, 10)
        self.assertEqual(result["merged"], [[0, 3], [5, 7]])
        self.assertEqual(result["gaps"], [[3, 5], [7, 10]])
        self.assertEqual(result["covered"], 5)

    def test_interval_strictly_inside_window(self):
        self.assertEqual(
            coverage([[4, 6]], 0, 10),
            {"merged": [[4, 6]], "gaps": [[0, 4], [6, 10]], "covered": 2},
        )

    def test_interval_exactly_the_window(self):
        self.assertEqual(coverage([[0, 10]], 0, 10),
                         {"merged": [[0, 10]], "gaps": [], "covered": 10})

    def test_window_strictly_inside_interval(self):
        self.assertEqual(coverage([[-5, 25]], 0, 10),
                         {"merged": [[0, 10]], "gaps": [], "covered": 10})

    def test_no_intervals(self):
        self.assertEqual(coverage([], 0, 5),
                         {"merged": [], "gaps": [[0, 5]], "covered": 0})

    def test_empty_window_ignores_everything(self):
        self.assertEqual(coverage([[0, 5]], 3, 3),
                         {"merged": [], "gaps": [], "covered": 0})
        self.assertEqual(coverage([], 7, 7),
                         {"merged": [], "gaps": [], "covered": 0})
        self.assertEqual(coverage([[-100, -50], [50, 100]], -3, -3),
                         {"merged": [], "gaps": [], "covered": 0})

    def test_empty_input_intervals_are_ignored(self):
        self.assertEqual(coverage([[2, 2], [1, 1]], 0, 5),
                         {"merged": [], "gaps": [[0, 5]], "covered": 0})

    def test_intervals_wholly_outside_are_ignored(self):
        self.assertEqual(
            coverage([[-100, -50], [50, 100]], 0, 10),
            {"merged": [], "gaps": [[0, 10]], "covered": 0},
        )
        self.assertEqual(coverage([[10, 20]], 0, 10),
                         {"merged": [], "gaps": [[0, 10]], "covered": 0})

    def test_clip_creates_adjacency(self):
        self.assertEqual(coverage([[0, 3], [3, 10]], 2, 8),
                         {"merged": [[2, 8]], "gaps": [], "covered": 6})

    def test_negative_bounds(self):
        self.assertEqual(
            coverage([[-10, -5], [-6, -3]], -8, -2),
            {"merged": [[-8, -3]], "gaps": [[-3, -2]], "covered": 5},
        )
        self.assertEqual(
            coverage([[-3, -1]], -10, -8),
            {"merged": [], "gaps": [[-10, -8]], "covered": 0},
        )

    def test_generator_input(self):
        result = coverage((pair for pair in [(0, 1), (1, 2)]), 0, 5)
        self.assertEqual(result, {"merged": [[0, 2]], "gaps": [[2, 5]], "covered": 2})

    def test_tuple_intervals(self):
        result = coverage(((0, 1), [1, 4]), 0, 4)
        self.assertEqual(result["merged"], [[0, 4]])

    def test_result_shape_and_types(self):
        result = coverage([[0, 1]], 0, 5)
        self.assertEqual(set(result), {"merged", "gaps", "covered"})
        self.assertIsInstance(result["merged"], list)
        self.assertIsInstance(result["gaps"], list)
        for lo, hi in result["merged"] + result["gaps"]:
            self.assertIs(type(lo), int)
            self.assertIs(type(hi), int)
        self.assertIs(type(result["covered"]), int)

    def test_covered_is_sum_of_merged_lengths(self):
        result = coverage([[0, 3], [10, 12], [20, 21]], 0, 30)
        self.assertEqual(result["covered"], sum(hi - lo for lo, hi in result["merged"]))

    def test_large_integers_not_enumerated(self):
        big = 10 ** 30
        result = coverage([[big, big + 5]], 0, big * 2)
        self.assertEqual(result, {
            "merged": [[big, big + 5]],
            "gaps": [[0, big], [big + 5, big * 2]],
            "covered": 5,
        })

    def test_huge_negative_integers(self):
        small = -(10 ** 40)
        result = coverage([[small, small + 10]], small - 10, small + 20)
        self.assertEqual(result, {
            "merged": [[small, small + 10]],
            "gaps": [[small - 10, small], [small + 10, small + 20]],
            "covered": 10,
        })


class ValidationTests(unittest.TestCase):
    def test_bool_endpoints_rejected(self):
        for bad in ([[True, 5]], [[0, False]], [[True, True]]):
            with self.assertRaises(ValueError):
                coverage(bad, 0, 10)

    def test_non_integer_endpoints_rejected(self):
        for bad in ([[0.5, 5]], [[0, 5.0]], [[None, 5]], [[0, "5"]], [["0", 5]]):
            with self.assertRaises(ValueError):
                coverage(bad, 0, 10)

    def test_reversed_interval_rejected(self):
        with self.assertRaises(ValueError):
            coverage([[5, 3]], 0, 10)

    def test_wrong_arity_rejected(self):
        for bad in ([[0]], [[0, 1, 2]], [[]], [()], [(0, 1, 2)]):
            with self.assertRaises(ValueError):
                coverage(bad, 0, 10)

    def test_non_sequence_interval_rejected(self):
        for bad in ([{0, 5}], ["ab"], [None], [5], [3.5], [{"lo": 0, "hi": 5}]):
            with self.assertRaises(ValueError):
                coverage(bad, 0, 10)

    def test_invalid_interval_outside_window_still_raises(self):
        with self.assertRaises(ValueError):
            coverage([[-5, -9]], 0, 10)
        with self.assertRaises(ValueError):
            coverage([[100, 200], [5, 3]], 0, 10)
        with self.assertRaises(ValueError):
            coverage([[-100, -50], [True, 5]], 0, 10)
        with self.assertRaises(ValueError):
            coverage([[100, 200], [10.5, 11]], 0, 10)

    def test_valid_distant_interval_is_ignored_not_an_error(self):
        self.assertEqual(
            coverage([[10 ** 20, 10 ** 20 + 4]], 0, 1),
            {"merged": [], "gaps": [[0, 1]], "covered": 0},
        )

    def test_invalid_late_item_is_still_detected(self):
        with self.assertRaises(ValueError):
            coverage([[0, 1], [2, 3], [7, 1]], 0, 4)

    def test_bound_validation(self):
        for start, end in ((True, 5), (0, False), (5, 0), (0.0, 1), ("0", 1), (None, 1), (0, None)):
            with self.assertRaises(ValueError):
                coverage([], start, end)
        self.assertEqual(coverage([], 0, 0)["covered"], 0)

    def test_non_iterable_intervals_rejected(self):
        for bad in (5, None, 3.5):
            with self.assertRaises(ValueError):
                coverage(bad, 0, 1)


class NoMutationTests(unittest.TestCase):
    def test_caller_list_is_untouched(self):
        data = [[3, 5], [-2, 2], [2, 4]]
        snapshot = copy.deepcopy(data)
        inner_ids = [id(item) for item in data]
        coverage(data, 0, 7)
        self.assertEqual(data, snapshot)
        self.assertEqual([id(item) for item in data], inner_ids)

    def test_caller_tuples_are_untouched(self):
        data = [(3, 5), (1, 2)]
        coverage(data, 0, 10)
        self.assertEqual(data, [(3, 5), (1, 2)])


class RandomizedTests(unittest.TestCase):
    def test_matches_brute_force(self):
        rng = random.Random(20240929)
        for _ in range(400):
            start = rng.randint(-12, 12)
            end = start + rng.randint(0, 12)
            intervals = []
            for _ in range(rng.randint(0, 6)):
                lo = rng.randint(-16, 16)
                hi = lo + rng.randint(0, 8)
                intervals.append([lo, hi] if rng.random() < 0.5 else (lo, hi))
            expected = brute_force(intervals, start, end)
            got = coverage(list(intervals), start, end)
            self.assertEqual(got, expected, msg=f"intervals={intervals} window=({start}, {end})")


